Write CTL2 code (no comments, no specific component for - so no transform() function) that processes the following JSON string input:

string json = "{\"orderId\":\"A-1001\",\"customer\":{\"id\":\"  C42 \",\"tier\":2},\"lines\":[{\"sku\":\"X1\",\"qty\":\"2\",\"unitPrice\":\"12.50\"},{\"sku\":\"X2\",\"qty\":3,\"unitPrice\":8.0},{\"sku\":\"X3\",\"qty\":null,\"unitPrice\":\"5\"},{\"sku\":\"X4\",\"qty\":\"1\",\"unitPrice\":null}],\"discountPct\":\"10\"}";

Task:
1) Parse json into a variant structure.
2) Compute decimal grossTotal = sum over lines of (qty * unitPrice) for lines where both qty and unitPrice are present and numeric. In this concrete input, parsed JSON numerics become integer/long or number, never decimal. qty may be string or integer/long; unitPrice may be string or number/integer/long. Non-numeric or null values should make that line contribute 0.
3) Compute integer validLineCount = number of lines that contributed to grossTotal (i.e., both parsed numeric values were present and usable).
4) Compute decimal netTotal = grossTotal * (1 - discountPct/100). In this concrete input, discountPct is a string; if missing/non-numeric, treat it as 0.
5) Extract string customerIdNormalized = customer.id lowercased and trimmed (null-safe -> "").

Then set global variables:
string customerIdNormalized;
decimal grossTotal;
decimal netTotal;
integer validLineCount;

Use variant type checks and casts appropriately. Output must compile and contain no comments.

```ctl
//#CTL2
string json = "{\"orderId\":\"A-1001\",\"customer\":{\"id\":\"  C42 \",\"tier\":2},\"lines\":[{\"sku\":\"X1\",\"qty\":\"2\",\"unitPrice\":\"12.50\"},{\"sku\":\"X2\",\"qty\":3,\"unitPrice\":8.0},{\"sku\":\"X3\",\"qty\":null,\"unitPrice\":\"5\"},{\"sku\":\"X4\",\"qty\":\"1\",\"unitPrice\":null}],\"discountPct\":\"10\"}";

variant root = parseJson(json);

string customerIdNormalized = "";
decimal grossTotal = 0D;
decimal netTotal = 0D;
integer validLineCount = 0;

if (!isnull(root) && (root typeof map)) {
    if (containsKey(root, "customer")) {
        variant cust = root["customer"];
        if (!isnull(cust) && (cust typeof map) && containsKey(cust, "id")) {
            variant idv = cust["id"];
            if (!isnull(idv)) {
                customerIdNormalized = lowerCase(trim(cast(idv, string)));
            }
        }
    }

    decimal discountPct = 0D;
    if (containsKey(root, "discountPct")) {
        variant dv = root["discountPct"];
        if (!isnull(dv) && (dv typeof string)) {
            string ds = cast(dv, string);
            if (isDecimal(ds)) {
                discountPct = str2decimal(ds);
            }
        }
    }

    if (containsKey(root, "lines")) {
        variant lines = root["lines"];
        if (!isnull(lines) && (lines typeof list)) {
            foreach (variant line : lines) {
                if (isnull(line) || !(line typeof map)) {
                    continue;
                }

                boolean hasQty = false;
                boolean hasPrice = false;
                decimal qtyDec = 0D;
                decimal priceDec = 0D;

                if (containsKey(line, "qty")) {
                    variant qv = line["qty"];
                    if (!isnull(qv)) {
                        if (qv typeof integer) {
                            qtyDec = cast(qv, integer);
                            hasQty = true;
                        } else if (qv typeof long) {
                            qtyDec = cast(qv, long);
                            hasQty = true;
                        } else if (qv typeof string) {
                            string qs = cast(qv, string);
                            if (isDecimal(qs)) {
                                qtyDec = str2decimal(qs);
                                hasQty = true;
                            }
                        }
                    }
                }

                if (containsKey(line, "unitPrice")) {
                    variant pv = line["unitPrice"];
                    if (!isnull(pv)) {
                        if (pv typeof number) {
                            priceDec = cast(pv, number);
                            hasPrice = true;
                        } else if (pv typeof integer) {
                            priceDec = cast(pv, integer);
                            hasPrice = true;
                        } else if (pv typeof long) {
                            priceDec = cast(pv, long);
                            hasPrice = true;
                        } else if (pv typeof string) {
                            string ps = cast(pv, string);
                            if (isDecimal(ps)) {
                                priceDec = str2decimal(ps);
                                hasPrice = true;
                            }
                        }
                    }
                }

                if (hasQty && hasPrice) {
                    grossTotal += qtyDec * priceDec;
                    validLineCount = validLineCount + 1;
                }
            }
        }
    }

    netTotal = grossTotal * (1D - (discountPct / 100D));
}
