`transformOnError(string errorMessage, string stackTrace)` runs when the normal group-level `transform()` fails. Populating `$out.0` and returning `OK` emits one fallback row so the failed batch remains visible downstream.

```ctl
//#CTL2
string currentBatchId = null;
boolean batchCaptured = false;
integer observedRows = 0;
integer weightedRows = 0;
decimal weightSum = 0D;
decimal maximumWeight = null;

function integer append() {
    if (!batchCaptured) {
        currentBatchId = $in.0.batch_id;
        batchCaptured = true;
    }

    observedRows++;
    if (!isnull($in.0.package_weight)) {
        decimal weight = $in.0.package_weight;
        weightSum += weight;
        weightedRows++;
        if (isnull(maximumWeight) || weight > maximumWeight) {
            maximumWeight = weight;
        }
    }
    return OK;
}

function integer transform() {
    $out.0.batch_id = currentBatchId;
    $out.0.avg_weight = weightedRows == 0
        ? null
        : round(weightSum / weightedRows, 2);
    $out.0.max_weight = maximumWeight;
    $out.0.observed_rows = observedRows;
    $out.0.failure_reason = null;
    return OK;
}

function integer transformOnError(string errorMessage, string stackTrace) {
    $out.0.batch_id = currentBatchId;
    $out.0.avg_weight = null;
    $out.0.max_weight = null;
    $out.0.observed_rows = observedRows;
    $out.0.failure_reason = "Batch aggregation failed: " + errorMessage;
    return OK;
}

function void clean() {
    currentBatchId = null;
    batchCaptured = false;
    observedRows = 0;
    weightedRows = 0;
    weightSum = 0D;
    maximumWeight = null;
}
